//! Cargo-driven `d3dx9_26.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x75f90000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff4a000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff4a000000u64)),
        o => panic!("d3dx9_26-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:d3d9", "import:d3dcompiler_47", "import:d3dxof", "import:ole32", "import:gdi32", "import:user32", "import:usp10", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:delayimp_rust"],
        "x86_64" => &["engine:wine", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:d3d9", "import:d3dcompiler_47", "import:d3dxof", "import:ole32", "import:gdi32", "import:user32", "import:usp10", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:delayimp_rust"],
        "aarch64" => &["engine:wine", "engine:c:dxguid", "engine:uuid", "engine:oldnames", "import:d3d9", "import:d3dcompiler_47", "import:d3dxof", "import:ole32", "import:gdi32", "import:user32", "import:usp10", "import:kernel32_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/d3dx9_26",
        "dll/directx/wine/d3dx9_26",
        "sdk/include/wine",
        "@build/sdk/include/wine",
        "dll/directx/wine/d3dx9_26/../d3dx9_36",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "D3DX_SDK_VERSION=26",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_USE_MATH_DEFINES",
        "_WIN32_WINNT=0x502",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("d3dx9_26_shims", &["dll/directx/wine/d3dx9_36/animation.c", "dll/directx/wine/d3dx9_36/core.c", "dll/directx/wine/d3dx9_36/effect.c", "dll/directx/wine/d3dx9_36/font.c", "dll/directx/wine/d3dx9_36/line.c", "dll/directx/wine/d3dx9_36/main.c", "dll/directx/wine/d3dx9_36/math.c", "dll/directx/wine/d3dx9_36/mesh.c", "dll/directx/wine/d3dx9_36/preshader.c", "dll/directx/wine/d3dx9_36/render.c", "dll/directx/wine/d3dx9_36/shader.c", "dll/directx/wine/d3dx9_36/skin.c", "dll/directx/wine/d3dx9_36/sprite.c", "dll/directx/wine/d3dx9_36/surface.c", "dll/directx/wine/d3dx9_36/texture.c", "dll/directx/wine/d3dx9_36/txc_compress_dxtn.c", "dll/directx/wine/d3dx9_36/txc_fetch_dxtn.c", "dll/directx/wine/d3dx9_36/util.c", "dll/directx/wine/d3dx9_36/volume.c", "dll/directx/wine/d3dx9_36/xfile.c"])
        .rc("dll/directx/wine/d3dx9_26/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/d3dx9_26/d3dx9_26.spec", "d3dx9_26.dll")
        .spec_stubs()
        .import_lib("dll/directx/wine/d3d9/d3d9.spec", "d3d9.dll", "d3d9")
        .import_lib("dll/directx/wine/d3dcompiler_47/d3dcompiler_47.spec", "d3dcompiler_47.dll", "d3dcompiler_47")
        .import_lib("dll/directx/wine/d3dxof/d3dxof.spec", "d3dxof.dll", "d3dxof")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/usp10/usp10.spec", "usp10.dll", "usp10")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/win32/windowscodecs/windowscodecs.spec", "windowscodecs.dll", "windowscodecs")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
